SELECT * FROM (SELECT product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, ROUND(AVG(units), 2) AS avg_units, COUNT(*) AS store_sale_count FROM store_sales GROUP BY product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS agg WHERE avg_units > 28 ORDER BY 3 DESC;
